// Absolute final Home controller: Home first, current clock, next-shift countdown, upcoming shifts, start/end shift and break controls.
(function(){
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function iso(d){return new Date(d).toISOString().slice(0,10)}
  function todayStr(){return iso(new Date())}
  function nowIso(){return new Date().toISOString()}
  function timeNow(){return new Date().toTimeString().slice(0,5)}
  function user(){return me()}
  function weekKey(date){var d=new Date(date+'T12:00:00');var n=(d.getDay()+6)%7;d.setDate(d.getDate()-n);return iso(d)}
  function isPublished(s){var wk=state.publishedWeeks&&state.publishedWeeks[weekKey(s.date)];return !!(s.publishedAt || (wk&&Array.isArray(wk.shiftIds)&&wk.shiftIds.includes(s.id)))}
  function visibleShift(s){return isAdmin()||isPublished(s)}
  function l(sid){return state.logs[sid]||{in:null,out:null,breaks:[]}}
  function liveShift(){return (state.shifts||[]).find(function(s){var x=l(s.id);return s.userId===state.currentUserId&&x.in&&!x.out})}
  function activeBreak(sid){return (l(sid).breaks||[]).find(function(b){return !b.end})}
  function hasScheduledPaidBreak(s){return !!(s.paidBreakScheduled||s.hasPaidBreak||Number(s.paidBreakMinutes||0)>0)}
  function hasShiftToday(){return (state.shifts||[]).some(function(s){return s.userId===state.currentUserId&&s.date===todayStr()&&visibleShift(s)})}
  function niceDate(d){return new Date(d+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}
  function upcoming(){var t=todayStr();return (state.shifts||[]).filter(function(s){return s.userId===state.currentUserId&&s.date>=t&&visibleShift(s)}).sort(function(a,b){return String(a.date).localeCompare(String(b.date))||String(a.start).localeCompare(String(b.start))})}
  function makeId(p){return p+'_'+Math.random().toString(36).slice(2,9)}
  function startDate(s){return new Date(s.date+'T'+(s.start||'00:00')+':00')}
  function nextShift(){var n=new Date();return upcoming().filter(function(s){return startDate(s)>n&&!l(s.id).out})[0]}
  function clockText(){return new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false})}
  function countdownText(s){if(!s)return 'No upcoming shift.';var m=Math.max(0,Math.floor((startDate(s)-new Date())/60000));var d=Math.floor(m/1440);var h=Math.floor((m%1440)/60);var r=m%60;var bits=[];if(d)bits.push(d+' day'+(d===1?'':'s'));if(h)bits.push(h+' hour'+(h===1?'':'s'));bits.push(r+' minute'+(r===1?'':'s'));return 'Starting in '+bits.join(', ')+' at '+(s.section||'work')}
  function homeClock(){var n=nextShift();return '<div class="homeClockCard"><div class="homeClockTime">'+clockText()+'</div><div class="homeCountdown">'+esc(countdownText(n))+'</div>'+(n?'<div class="homeNextShiftLine">'+esc(n.section)+', '+esc(n.start)+' - '+esc(n.end)+'</div>':'')+'</div>'}
  function topShell(inner){var u=user(),set=state.permissionSets[u.permissionSetId]||{name:'Staff'};var nav=['<button class="tab '+(state.view==='home'?'active':'')+'" onclick="setView(\'home\')">Home</button>','<button class="tab '+(state.view==='rota'?'active':'')+'" onclick="setView(\'rota\')">Schedule</button>'];if(can('viewPeople')||can('manageUsers'))nav.push('<button class="tab '+(state.view==='people'?'active':'')+'" onclick="setView(\'people\')">People</button>');if(isAdmin())nav.push('<button class="tab '+(state.view==='admin'?'active':'')+'" onclick="setView(\'admin\')">Admin</button>');document.getElementById('app').innerHTML='<header class="topbar"><div><h1>Rota App</h1><p>'+esc(u.name)+' · '+esc(set.name||'Staff')+'</p></div><div class="topActions"><select id="currentUserSelect">'+state.users.map(function(x){return '<option value="'+x.id+'" '+(x.id===state.currentUserId?'selected':'')+'>'+esc(x.nickname||x.name)+' ('+esc((state.permissionSets[x.permissionSetId]||{}).name||'Staff')+')</option>'}).join('')+'</select></div></header><nav class="tabs">'+nav.join('')+'</nav><main>'+inner+'</main>';document.getElementById('currentUserSelect').onchange=function(e){state.currentUserId=e.target.value;save();render()}}
  function shiftButtons(s){var live=liveShift(),x=l(s.id),b=activeBreak(s.id);if(live&&live.id===s.id){if(b)return '<button class="breakEndBtn" onclick="endBreak(\''+s.id+'\')">End Break</button>';return '<button class="endShiftBtn" onclick="clockOut(\''+s.id+'\')">End Shift</button><button class="breakUnpaidBtn" onclick="startBreak(\''+s.id+'\',false)">Start Unpaid Break</button>'+(hasScheduledPaidBreak(s)?'<button class="breakPaidBtn" onclick="startBreak(\''+s.id+'\',true)">Start Paid Break</button>':'')}if(!live&&s.date===todayStr()&&!x.out)return '<button class="startShiftBtn" onclick="clockIn(\''+s.id+'\')">Start Shift</button>';return ''}
  function shiftCard(s){var st=l(s.id),status=st.in&&!st.out?'On shift':st.out?'Completed':s.date===todayStr()?'Today':'Upcoming';return '<div class="homeShiftCard"><div><strong>'+esc(niceDate(s.date))+'</strong><h3>'+esc(s.start)+' - '+esc(s.end)+'</h3><p>'+esc(s.section)+'</p><p class="muted">'+esc(status+(s.notes?' · '+s.notes:''))+'</p></div><div class="homeShiftActions">'+shiftButtons(s)+'</div></div>'}
  function unscheduledBox(live){if(hasShiftToday())return '';return '<div class="workCard unscheduledHomeBox"><h3>Start unscheduled shift</h3><p class="muted">Use this if no shift has been added for you today.</p><label>Section<select id="unscheduledSection">'+(state.sections||[]).map(function(s){return '<option>'+esc(s)+'</option>'}).join('')+'</select></label><label>Note<input id="unscheduledNote" placeholder="Optional duty note"></label><button class="startShiftBtn unscheduledStartBtn" '+(live?'disabled':'')+' onclick="startUnscheduledShift()">Start Unscheduled Shift</button></div>'}
  window.renderHome=function(){var ss=upcoming(),live=liveShift();var html='<section class="panel homePanel">'+homeClock()+unscheduledBox(live)+'<h2>Upcoming shifts</h2><div class="homeShiftList">'+(ss.length?ss.map(shiftCard).join(''):'<p class="muted">No upcoming shifts.</p>')+'</div></section>';topShell(html);window.scrollTo(0,0)};
  window.clockIn=function(id){if(liveShift())return alert('You are already clocked in.');var s=(state.shifts||[]).find(function(x){return x.id===id});if(!s)return;var t=timeNow();s.start=t;s.actualStart=t;state.logs[id]={...l(id),in:nowIso(),out:null};save();renderHome()};
  window.clockOut=function(id){var s=(state.shifts||[]).find(function(x){return x.id===id});if(!s)return;var t=timeNow();var log=l(id);log.out=nowIso();state.logs[id]=log;s.end=t;s.actualEnd=t;if(s.unscheduled)s.end=t;save();renderHome()};
  window.startBreak=function(id,paid){var log=l(id);if((log.breaks||[]).some(function(b){return !b.end}))return alert('There is already an active break. End that break first.');log.breaks=log.breaks||[];log.breaks.push({id:makeId('break'),start:nowIso(),end:null,paid:!!paid});state.logs[id]=log;save();renderHome()};
  window.endBreak=function(id){var log=l(id);var b=(log.breaks||[]).find(function(x){return !x.end});if(!b)return alert('No active break to end.');b.end=nowIso();state.logs[id]=log;save();renderHome()};
  window.startUnscheduledShift=function(){if(liveShift())return alert('You are already clocked in.');if(hasShiftToday())return alert('You already have a shift today. Start that scheduled shift instead.');var section=document.getElementById('unscheduledSection')?.value||state.sections?.[0]||'Unassigned';var note=document.getElementById('unscheduledNote')?.value||'Unscheduled shift';var sid=makeId('s'),t=timeNow();state.shifts.push({id:sid,userId:state.currentUserId,section:section,date:todayStr(),start:t,end:t,actualStart:t,notes:note,unscheduled:true,publishedAt:new Date().toISOString()});state.logs[sid]={in:nowIso(),out:null,breaks:[]};save();renderHome()};
  window.renderClock=window.renderHome;
  window.setView=function(v){state.view=(v==='clock'?'home':v);if(state.view==='admin')state.adminPanel='menu';save();render()};
  window.render=function(){if(state.view==='home'||state.view==='clock')renderHome();else if(state.view==='rota')renderRota();else if(state.view==='people')renderPeople();else if(state.view==='profile')renderProfile();else if(state.view==='profileEdit')renderProfileEdit();else if(state.view==='admin')renderAdmin();else renderHome()};
  try{renderClock=window.renderClock;setView=window.setView;render=window.render;clockIn=window.clockIn;clockOut=window.clockOut;startBreak=window.startBreak;endBreak=window.endBreak;startUnscheduledShift=window.startUnscheduledShift}catch(e){}
  if(!state.view||state.view==='rota'||state.view==='clock'){state.view='home';save();}
  render();
})();
